-- Diagnostico de productos legacy sin match unico en public.products (Materiales / branch_id = 1)
-- Ejecutar en Supabase SQL Editor. No modifica datos finales.

begin;

create temporary table tmp_legacy_sales (
  legacy_sale_id bigint primary key,
  legacy_customer_id bigint,
  legacy_folio text,
  issue_date date,
  due_date date,
  credit_days_applied integer,
  total numeric,
  credito integer,
  liquidado integer,
  paid_amount_legacy_field numeric,
  direccion text,
  usuario text,
  vendedor text,
  legacy_status integer,
  customer_name text
) on commit drop;




create temporary table tmp_legacy_sale_items (
  legacy_sale_id bigint,
  legacy_sale_item_id bigint primary key,
  legacy_product_id bigint,
  legacy_presentation_id bigint,
  product_name text,
  product_name_normalized text,
  legacy_barcode text,
  presentation_name text,
  presentation_name_normalized text,
  tipoventa text,
  cantidad numeric,
  factor_a_base numeric,
  qty_base_calculated numeric,
  catalog_wholesale_price numeric,
  catalog_retail_price numeric,
  pespecial integer,
  unitarioespecial numeric,
  unit_price_used numeric,
  subtotal numeric
) on commit drop;







create temporary table tmp_target_notes as
select
  cn.id as credit_note_id,
  replace(cn.folio, 'LEG-', '')::bigint as legacy_sale_id
from public.credit_notes cn
where cn.branch_id = 1
  and cn.balance > 0
  and cn.folio ~ '^LEG-[0-9]+$'
  and exists (
    select 1 from tmp_legacy_sales ls
    where ls.legacy_sale_id = replace(cn.folio, 'LEG-', '')::bigint
  );

create temporary table tmp_product_candidates as
select
  lsi.legacy_product_id,
  lsi.product_name,
  lsi.product_name_normalized,
  p.id as product_id,
  p.name as current_product_name,
  p.barcode as current_barcode,
  p.sku as current_sku,
  p.is_active,
  count(*) over (partition by lsi.legacy_product_id) as candidate_count,
  count(*) filter (where coalesce(p.is_active, true)) over (partition by lsi.legacy_product_id) as active_candidate_count,
  row_number() over (
    partition by lsi.legacy_product_id
    order by case when coalesce(p.is_active, true) then 0 else 1 end, p.id
  ) as rn
from (
  select distinct lsi.legacy_product_id, lsi.product_name, lsi.product_name_normalized
  from tmp_legacy_sale_items lsi
  join tmp_target_notes tn on tn.legacy_sale_id = lsi.legacy_sale_id
) lsi
join public.products p
  on p.branch_id = 1
 and upper(trim(p.name)) = lsi.product_name_normalized;

create temporary table tmp_product_match as
select
  legacy_product_id,
  product_name,
  product_name_normalized,
  product_id,
  current_product_name
from tmp_product_candidates
where (active_candidate_count = 1 and is_active is true)
   or (candidate_count = 1 and rn = 1);

select
  lsi.legacy_product_id,
  max(lsi.product_name) as legacy_product_name,
  max(lsi.product_name_normalized) as legacy_product_name_normalized,
  count(distinct pc.product_id) as candidate_count,
  string_agg(
    distinct concat(
      pc.product_id,
      ' :: ',
      pc.current_product_name,
      ' :: barcode=',
      coalesce(pc.current_barcode, '-'),
      ' :: sku=',
      coalesce(pc.current_sku, '-'),
      ' :: activo=',
      case when pc.is_active then '1' else '0' end
    ),
    ' | '
  ) as candidate_products
from (
  select distinct lsi.legacy_product_id, lsi.product_name, lsi.product_name_normalized
  from tmp_legacy_sale_items lsi
  join tmp_target_notes tn on tn.legacy_sale_id = lsi.legacy_sale_id
) lsi
left join tmp_product_candidates pc
  on pc.legacy_product_id = lsi.legacy_product_id
left join tmp_product_match pm
  on pm.legacy_product_id = lsi.legacy_product_id
where pm.product_id is null
group by lsi.legacy_product_id
order by legacy_product_name;

rollback;
